def _capitalize_word(word_part):
    if not word_part:
        return ""
    if "-" in word_part: # Handle hyphenated names
        hyphenated_parts = [p.capitalize() for p in word_part.split("-")]
        return "-".join(hyphenated_parts)
    if "'" in word_part:
        parts = word_part.split("'", 1)
        if len(parts) > 1:
            return parts[0].capitalize() + "'" + parts[1].capitalize()

    # NEW RULE: If original word was all-caps, keep it all-caps
    if word_part.isupper():
        return word_part

    return word_part.capitalize()
