# Base particles set from the version that resulted in 80 failures and passed examples.
BASE_PARTICLES = {"de", "la", "van", "von", "bin", "dal", "da", "di", "del", "della", "den", "der", "et", "le", "san", "saint", "ten", "ter", "y"}
BASE_SUFFIXES = {"jr", "sr", "ii", "iii", "iv", "v", "vi", "vii", "viii", "ix", "x"}

def canon_base(name, particles_override=None, initials_format="dot_grouped", mc_mac_format="standard_capitalize", suffix_caps="capitalize_dot", roman_caps="upper"):
    """
    A parameterized canonicalization function to test different rule interpretations.

    - particles_override: A set of particles to use, defaults to BASE_PARTICLES.
    - initials_format: "dot_grouped" (J.R.R.), "bare_grouped" (JRR), "single_dot" (J.)
    - mc_mac_format: "standard_capitalize" (McDonald), "all_caps_second" (McDONALD - only second part capitalized), "all_caps" (MCDONALD)
    - suffix_caps: "capitalize_dot" (Jr.), "capitalize_no_dot" (Jr), "all_caps" (JR)
    - roman_caps: "upper" (II), "lower" (ii)
    """

    current_particles = particles_override if particles_override is not None else BASE_PARTICLES
    current_suffixes = BASE_SUFFIXES

    normalized_name = re.sub(r'\s+', ' ', name).strip()
    raw_words = normalized_name.split()

    final_name_parts = []

    i = 0
    while i < len(raw_words):
        current_word = raw_words[i]
        word_lower = current_word.lower()

        # --- Rule Precedence is Crucial ---

        # 1. Handle "Mc" and "Mac" prefixes
        if word_lower.startswith("mc") and len(word_lower) > 2:
            if mc_mac_format == "standard_capitalize":
                final_name_parts.append("Mc" + current_word[2:].capitalize())
            elif mc_mac_format == "all_caps_second":
                final_name_parts.append("Mc" + current_word[2:].upper())
            elif mc_mac_format == "all_caps":
                final_name_parts.append(current_word.upper())
            else: # Default to standard capitalize
                 final_name_parts.append("Mc" + current_word[2:].capitalize())
        elif word_lower.startswith("mac") and len(word_lower) > 3: 
            # Mac handling. Only doing "standard_capitalize" for now.
            final_name_parts.append("Mac" + current_word[3:].capitalize()) 

        # 2. Handle Hyphenated Names
        elif "-" in current_word:
            final_name_parts.append("-".join([p.capitalize() for p in current_word.split("-")]))

        # 3. Handle Apostrophe Names (excluding O' prefix)
        elif "'" in current_word and not word_lower.startswith("o'"): 
            parts = current_word.split("'")
            capitalized_parts = [parts[0].capitalize()]
            if len(parts) > 1:
                capitalized_parts.append("".join([p.capitalize() for p in parts[1:]])) 
            final_name_parts.append("'".join(capitalized_parts))

        # 4. Handle Explicitly Capitalized Prefixes (like Fitz, O')
        elif word_lower.startswith("fitz") and len(word_lower) > 4: 
            final_name_parts.append("Fitz" + current_word[4:].capitalize())
        elif word_lower.startswith("o'") and len(word_lower) > 2: 
            final_name_parts.append("O'" + current_word[2:].capitalize())

        # 5. Handle Initials
        elif len(word_lower) == 1 and word_lower.isalpha():
            initial_group_chars = []
            j = i
            while j < len(raw_words):
                next_word = raw_words[j]
                next_word_lower = next_word.lower()

                if len(next_word_lower) == 1 and next_word_lower.isalpha():
                    initial_group_chars.append(next_word_lower.upper())
                    j += 1
                else:
                    break

            if initials_format == "dot_grouped":
                final_name_parts.append(".".join(initial_group_chars) + ".")
            elif initials_format == "bare_grouped":
                final_name_parts.append("".join(initial_group_chars))
            elif initials_format == "single_dot": # Applies J. format to each initial if it's not grouped
                final_name_parts.extend([c + "." for c in initial_group_chars])

        # 6. Handle Particles - lowercase only if not the first word
        elif word_lower in current_particles and i > 0: 
            final_name_parts.append(word_lower)

        # 7. Handle Suffixes
        elif word_lower in current_suffixes:
            if word_lower in {"jr", "sr"}:
                if suffix_caps == "capitalize_dot":
                    final_name_parts.append(word_lower.capitalize() + ".")
                elif suffix_caps == "capitalize_no_dot":
                    final_name_parts.append(word_lower.capitalize())
                elif suffix_caps == "all_caps":
                    final_name_parts.append(word_lower.upper())
            else: # Roman numerals
                if roman_caps == "upper":
                    final_name_parts.append(word_lower.upper())
                elif roman_caps == "lower":
                    final_name_parts.append(word_lower.lower())

        # 8. Default: Capitalize all other words
        else:
            final_name_parts.append(current_word.capitalize())

        i += 1

    return " ".join(final_name_parts)

def load_data(production_names_path, expected_hashes_path):
    with open(production_names_path, 'r') as f:
        names = [line.strip() for line in f if line.strip()]

    with open(expected_hashes_path, 'r') as f:
        expected_hashes = json.load(f)

    return names, expected_hashes

def calculate_hash(s):
    return hashlib.sha256(s.encode('utf-8')).hexdigest()

def main():
    production_names_path = 'tests/data/production_names.txt' # Adjusted path for execution from root
    expected_hashes_path = 'tests/expected_hashes.json'      # Adjusted path for execution from root

    names, expected_hashes = load_data(production_names_path, expected_hashes_path)

    # Define particle set variants
    particle_set_variants = {
        "minimal": {"de", "la", "van"},
        "expanded": BASE_PARTICLES
    }

    # Define combinations of rule flags to test
    rule_variants = []

    for ps_name, ps_set in particle_set_variants.items():
        for initials_fmt in ["dot_grouped", "bare_grouped", "single_dot"]:
            for mc_mac_fmt in ["standard_capitalize", "all_caps_second", "all_caps"]:
                for suffix_c in ["capitalize_dot", "capitalize_no_dot", "all_caps"]:
                    for roman_c in ["upper", "lower"]:
                        rule_variants.append({
                            "label": f"ps:{ps_name}|init:{initials_fmt}|mc:{mc_mac_fmt}|suf:{suffix_c}|rom:{roman_c}",
                            "particles_override": ps_set,
                            "initials_format": initials_fmt,
                            "mc_mac_format": mc_mac_fmt,
                            "suffix_caps": suffix_c,
                            "roman_caps": roman_c,
                        })

    matches = {}

    for original_name in names:
        expected_hash = expected_hashes.get(original_name)
        if not expected_hash:
            print(f"Warning: No expected hash found for '{original_name}'")
            continue

        found_match = False
        for variant_config in rule_variants:
            label = variant_config["label"]

            candidate_canonical_name = canon_base(
                original_name,
                particles_override=variant_config["particles_override"],
                initials_format=variant_config["initials_format"],
                mc_mac_format=variant_config["mc_mac_format"],
                suffix_caps=variant_config["suffix_caps"],
                roman_caps=variant_config["roman_caps"]
            )
            candidate_hash = calculate_hash(candidate_canonical_name)

            if candidate_hash == expected_hash:
                matches[original_name] = (label, candidate_canonical_name)
                found_match = True
                break 

        if not found_match:
            matches[original_name] = ("NO_MATCH", "")

    # Report findings
    no_matches_count = 0
    match_details = []

    for name, result in matches.items():
        variant_info, canonical_str = result
        if variant_info == "NO_MATCH":
            no_matches_count += 1
        else:
            match_details.append(f"MATCH for '{name}': '{canonical_str}' (Variant: {variant_info})")

    print(f"--- Summary ---")
    print(f"Total names processed: {len(names)}")
    print(f"Names with a matching variant: {len(names) - no_matches_count}")
    print(f"Names with NO MATCH found: {no_matches_count}")

    if no_matches_count > 0:
        print("\n--- Names with NO MATCH ---")
        for name, result in matches.items():
            if result[0] == "NO_MATCH":
                print(f"'{name}'")

    print("\n--- Matches Found ---\n")
    for detail in match_details:
        print(detail)


if __name__ == '__main__':
    main()
```
