"""Canonicalize a person's display name to the company house style."""

_PARTICLES = {"de", "la", "van", "di", "del", "della", "do", "du", "da", "der", "ter", "bin", "al", "ten"}
# "von" removed - NOT a particle, capitalizes normally

_SUFFIXES = {"sr", "jr", "ii", "iii", "iv", "v", "vi", "vii", "viii"}


def _is_all_caps(word):
    return len(word) > 1 and word.isupper() and word.isalpha()


def _cap_word(word):
    if not word:
        return word
    if "'" in word:
        idx = word.index("'")
        return word[:idx].capitalize() + "'" + word[idx+1:].lower()
    if "-" in word:
        return "-".join(p.capitalize() for p in word.split("-"))
    return word.capitalize()


def _cap_name_word(word):
    lower = word.lower()
    if lower.startswith("mc") and len(lower) > 2 and word[2:3].isalpha():
        return "Mc" + _cap_word(word[2:])
    return _cap_word(word)


def canon(name):
    words = name.strip().split()
    if not words:
        return ""

    result = []
    initials = []

    for word in words:
        lower = word.lower()

        if len(word) == 1 and word.isalpha():
            initials.append(word.upper())
            continue

        if len(word) == 2 and word[1] == "." and word[0].isalpha():
            initials.append(word[0].upper())
            continue

        if initials:
            result.append(".".join(initials) + ".")
            initials = []

        if _is_all_caps(word):
            result.append(word)
        elif lower in _SUFFIXES:
            result.append(lower.upper())
        elif lower in _PARTICLES and (result or initials):
            result.append(lower)
        else:
            result.append(_cap_name_word(word))

    if initials:
        result.append(".".join(initials) + ".")

    return " ".join(result)
