"""Canonicalize a person's display name to the company house style."""

PARTICLES = {"de","la","van","von","da","di","du","del","della","der","den",
             "ter","bin","al","ten","li"}
SUFFIXES = {"jr","sr","ii","iii","iv","v","vi","vii","viii","ix","x"}

def _cap(word):
    return word[:1].upper() + word[1:].lower() if word else word

def _fix_word(w):
    low = w.lower()
    # Mc / Mac prefixes
    if low.startswith("mc") and len(low) > 2:
        return "Mc" + _cap(w[2:])
    if low.startswith("mac") and len(low) > 3:
        return "Mac" + _cap(w[3:])
    # O'Brien / D'Angelo
    if "'" in low:
        parts = low.split("'")
        return "'".join(_cap(p) for p in parts)
    # hyphenated
    if "-" in low:
        return "-".join(_cap(p) for p in low.split("-"))
    return _cap(w)

def _is_initial(tok):
    t = tok.rstrip(".")
    return len(t) == 1 and t.isalpha()

def canon(name):
    toks = name.split()
    n = len(toks)
    out = []
    i = 0
    while i < n:
        tok = toks[i]
        low = tok.lower().rstrip(".")
        if _is_initial(tok):
            group = []
            while i < n and _is_initial(toks[i]):
                group.append(toks[i].rstrip(".").upper() + ".")
                i += 1
            out.append("".join(group))
            continue
        if low in SUFFIXES:
            out.append(low.upper())
            i += 1
            continue
        if low in PARTICLES and len(out) > 0:
            out.append(low)
            i += 1
            continue
        out.append(_fix_word(tok))
        i += 1
    return " ".join(out)
