def canon(name):
    """Return the house-canonical form of a display name."""
    words = name.strip().split()
    processed_words = []
    initials_buffer = []

    for i, word in enumerate(words):
        # Check if the word is an initial (single letter, possibly with a dot)
        clean_word = word.replace('.', '') # strip any existing dots for initial check

        if len(clean_word) == 1 and clean_word.isalpha():
            initials_buffer.append(clean_word.upper())
        else:
            # If we were collecting initials, flush them before processing the current non-initial word
            if initials_buffer:
                processed_words.append(".".join(initials_buffer) + ".")
                initials_buffer = [] # Reset buffer

            # Process the current non-initial word
            if i == 0: # First word is always capitalized
                processed_words.append(_capitalize_word(word))
            elif word.lower() in _LOWERCASE_PARTICLES:
                processed_words.append(word.lower())
            elif word.lower().startswith("mc") and len(word) > 2 and word[2].isalpha():
                processed_words.append("Mc" + _capitalize_word(word[2:]))
            elif word.lower().startswith("mac") and len(word) > 3 and word[3].isalpha():
                processed_words.append("Mac" + _capitalize_word(word[3:]))
            else:
                processed_words.append(_capitalize_word(word))

    # Flush any remaining initials at the end of the name
    if initials_buffer:
        processed_words.append(".".join(initials_buffer) + ".")

