import json, pathlib
from decimal import Decimal, ROUND_HALF_UP, ROUND_HALF_EVEN, ROUND_HALF_DOWN

LED = json.loads((pathlib.Path("tests/reference_totals.json")).read_text())

def q(x, mode):
    return Decimal(str(x)).quantize(Decimal("0.01"), rounding=mode)

def compute(lines, tax, backend, per_line, mode):
    if backend == "float":
        def rnd(v):
            if mode == "py": return round(v, 2)
            return float(q(v, mode))
        sub = 0.0
        for qy, up, dp in lines:
            net = qy*up*(1-dp/100)
            sub += rnd(net) if per_line else net
        return rnd(sub*(1+tax/100))
    else:
        D = lambda v: Decimal(str(v))
        def rnd(v):
            m = ROUND_HALF_EVEN if mode=="py" else mode
            return v.quantize(Decimal("0.01"), rounding=m)
        sub = Decimal("0")
        for qy, up, dp in lines:
            net = D(qy)*D(up)*(Decimal(1)-D(dp)/Decimal(100))
            sub += rnd(net) if per_line else net
