"""Canonicalize a person's display name to the company house style."""

import re

PARTICLES = {"de", "la", "van", "von", "der", "ter", "den", "del", "della",
             "di", "da", "du", "ten", "bin", "al"}
SUFFIXES = {"jr", "sr", "ii", "iii", "iv", "v", "vi", "vii", "viii"}
APOS = chr(39)


def _cap(token):
    # capitalize across apostrophes and hyphens; lowercase the rest
    for sep in (APOS, "-"):
        if sep in token:
            return sep.join(_cap(p) for p in token.split(sep))
    low = token.lower()
    if low.startswith("mc") and len(low) > 2:
        return "Mc" + low[2:].capitalize()
    if low.startswith("mac") and len(low) > 3:
        return "Mac" + low[3:].capitalize()
    return low.capitalize()


def canon(name):
    raw = re.sub(r"\s+", " ", name).strip().split()
    n = len(raw)
    out = []
    i = 0
    while i < n:
        w = raw[i]
        low = w.lower().rstrip(".")
        is_last = (i == n - 1)

        # suffix only if it is the final token
        if is_last and low in SUFFIXES and low != "v":
            out.append(low.upper() if low not in ("jr", "sr") else low.capitalize())
            i += 1
            continue
        if is_last and low == "v" and i > 0:
            out.append("V")
            i += 1
            continue

        # initials run: single letters (optionally with a dot), not the trailing suffix
        single = len(low) == 1 and low.isalpha()
        if single and not (is_last and low == "v" and i > 0):
            chars = []
            j = i
            while j < n:
                t = raw[j].lower().rstrip(".")
                last_t = (j == n - 1)
                if len(t) == 1 and t.isalpha() and not (last_t and t == "v" and j > 0):
                    chars.append(t.upper())
                    j += 1
                else:
                    break
            out.append(".".join(chars) + ".")
            i = j
            continue

        if low in PARTICLES and i > 0:
            out.append(low)
            i += 1
            continue

        out.append(_cap(w))
        i += 1

    return " ".join(out)

