"""Canonicalize a person's display name to the company house style."""

APOS = chr(39)  # the ' character

PARTICLES = {"de", "la", "van", "von", "der", "den", "del", "della",
             "di", "du", "da", "ter", "ten", "bin", "al"}
SUFFIXES = {"ii", "iii", "iv", "v", "vi", "vii", "viii", "jr", "sr"}


def _is_initial(tok):
    t = tok.rstrip(".")
    return len(t) == 1 and t.isalpha()


def _fix_word(w):
    low = w.lower()
    if "-" in low:
        return "-".join(_fix_word(p) for p in low.split("-"))
    if APOS in low:
        a, b = low.split(APOS, 1)
        return a.capitalize() + APOS + b.capitalize()
    if low.startswith("mc") and len(low) > 2:
        return "Mc" + low[2:].capitalize()
    if low.startswith("mac") and len(low) > 3:
        return "Mac" + low[3:].capitalize()
    return low.capitalize()


def canon(name):
    toks = name.split()
    out = []
    i = 0
    n = len(toks)
    while i < n:
        tok = toks[i]
        low = tok.lower()
        if _is_initial(tok):
            group = []
            while i < n and _is_initial(toks[i]):
                group.append(toks[i].rstrip(".")[0].upper())
                i += 1
            out.append(".".join(group) + ".")
            continue
        if low in PARTICLES and out:
            out.append(low)
        elif low in SUFFIXES:
            if low in {"jr", "sr"}:
                out.append(low.capitalize() + ".")
            else:
                out.append(low.upper())
        else:
            out.append(_fix_word(tok))
        i += 1
    return " ".join(out)
